SourceCode.Declaration:
[TFMListELementAttribute('textElement')]
class TFMListTextElement extends TFMListElement
{
    str text;
    str dataMember;    
    TFMFontId fontId;

}

Method.Source:
public static TFMListTextElement Construct()
{
    return new TFMListTextElement();
}

public static TFMListTextElement ConstructTextElement(str _text, TFMFontID _fontId, TFMListXAlign _xAlign = SysChartHorizontalAlignment::Left, TFMListYAlign _yAlign = TFMVerticalAlignment::Top)
{
    TFMListTextElement txtElement = TFMListTextElement::Construct();
    txtElement.parmText(_text);
    txtElement.parmFontId(_fontId);
    txtElement.parmHorizontalAlignment(_xAlign);
    txtElement.parmVerticalAlignment(_yAlign);
    return txtElement;
}

public TFMListValueElement addValueElement(TFMDataSetField _text, TFMFontID _fontId)
{
    TFMListValueElement valueElement = new TFMListValueElement();
    valueElement.parmText(_text);
    valueElement.parmFontId(_fontId);

    this.addChild(valueElement);
    return valueElement;
}

public void appendToXML(XmlElement _parent, boolean _expandCustomComponents)

{
    XmlElement textElement =_parent.ownerDocument().createElement('textElement');
    XmlElement		valuesNode;
    TFMListBase	    valueElement;
    MapEnumerator	mEnum;

    textElement.setAttribute('fontId',fontId);
    textElement.setAttribute('text',text);

    if(horizontalAlignment != SysChartHorizontalAlignment::Auto)
    {
        textElement.setAttribute('horizontalAlignment', strLwr(enum2Symbol(enumNum(SysChartHorizontalAlignment), horizontalAlignment)));
    }
    textElement.setAttribute('verticalAlignment', strLwr(enum2Symbol(enumNum(TFMVerticalAlignment), verticalAlignment)));
    if (dataMember)
    {
        textElement.setAttribute('dataMember',dataMember);
    }
    if (baseChildren && baseChildren.elements())
    {
        mEnum = baseChildren.getEnumerator();
        while(mEnum.moveNext())
        {
            valueElement = mEnum.currentValue();
            valueElement.appendToXML(textElement, _expandCustomComponents);
        }
    }
    _parent.appendChild(textElement);
}

[TFMParameter('{DisplayLine1}')]
public TFMDataSetField parmText(str _text = text)
{
    text = _text;
    return text;
}

[TFMParameter('')]
public TFMDataSetField parmDataMember(str _dataMember = dataMember)
{
    dataMember = _dataMember;
    return dataMember;
}

[TFMParameter('')]
public TFMFontId parmFontId(TFMFontId _fontId = fontId)
{
    fontId = _fontId;
    return fontId;
}
